# coding: utf-8
from pathlib import Path
import json
import pandas as pd
s=pd.read_csv('results/comparison.csv',index_col=0)
d=json.loads(Path('results/dqn/selection.json').read_text())
b=json.loads(Path('results/baseline_selection.json').read_text())
seeds=pd.read_csv('results/dqn/test_seeds.csv')
meta=json.loads(Path('data/processed.json').read_text())
t=pd.read_csv('results/test_dqn.csv')
lines=['# Результаты Twitter: шардинг и нейросетевое управление','',f"Проанализированы {meta['rows']:,} запросов к {meta['unique_keys']:,} ключам за первые 168 часов выборки cluster7 sample100. Данные — запросы get/set к кешу, а не твиты.",'','## Обучение','',f"DQN: 12 конфигураций по 160 эпизодов, затем 3 финалиста × 3 seed × 400 эпизодов. Всего 2 119 680 взаимодействий с train-симулятором. Выбранная сеть: 10 → {d['hidden']} → {d['hidden']} → 3, learning rate {d['lr']}, gamma {d['gamma']}; seed {d['seed']}, лучший validation-checkpoint на эпизоде {d['best_episode']}. Веса: results/dqn/{d['name']}.npz.",'','Веса оптимизируются Adam; это настоящая нейросеть Double DQN, реализованная в NumPy. Сетка параметров ограничена и не гарантирует глобально лучшего решения. Табличный Q-learning обучался в 12 запусках по 600 эпизодов. Четыре дня train повторялись, новые данные этим не создавались. Все параметры и checkpoint выбирались по validation; test открыт после заморозки выбора.','', '## Последние 48 часов: итоговая стоимость','', '| Стратегия | Стоимость | Интервалов с превышением | Среднее шардов | Перенос, МБ | Изменений |','|---|---:|---:|---:|---:|---:|']
for name in [b['fixed'],'threshold','q_learning','dqn','fixed_4']:
 r=s.loc[name];label=name+(' (выбран на validation)' if name==b['fixed'] else (' (контекст после test)' if name=='fixed_4' else ''))
 lines.append(f"| {label} | {r['cost']:.2f} | {r['overloaded_slots']:.0f} / 192 | {r['mean_shards']:.2f} | {r['moved_mb']:.2f} | {r['changes']:.0f} |")
lines+=['',f"DQN дешевле пороговой стратегии на {(s.loc['threshold','cost']-s.loc['dqn','cost'])/s.loc['threshold','cost']*100:.2f}%. По сравнению с фиксированным вариантом, выбранным на validation ({b['fixed']}), экономия {(s.loc[b['fixed'],'cost']-s.loc['dqn','cost'])/s.loc[b['fixed'],'cost']*100:.2f}%. Четыре фиксированных шарда — лучший фиксированный вариант именно на test; это наблюдение после теста, а не честный выбор до него. Даже относительно него стоимость DQN ниже на {(s.loc['fixed_4','cost']-s.loc['dqn','cost'])/s.loc['fixed_4','cost']*100:.2f}%.",'',f"Выбранный агент использовал от {t.shards.min()} до {t.shards.max()} шардов, изменил число шардов {int(s.loc['dqn','changes'])} раза. Но превышение мощности возникло в {int(s.loc['dqn','overloaded_slots'])} интервалах против {int(s.loc['threshold','overloaded_slots'])} у пороговой стратегии. Агент экономит серверы ценой большей перегрузки; он не улучшает все показатели одновременно. Нельзя утверждать, что он лучше обеспечивает SLA.",'', '## Чувствительность к случайным весам','']
for r in seeds.to_dict('records'):lines.append(f"- Seed {r['seed']}: test cost {r['cost']:.2f}.")
lines+=['',f"Среднее test cost трёх seed выбранной конфигурации: {seeds.cost.mean():.2f}, стандартное отклонение: {seeds.cost.std():.2f}. Это разброс инициализаций на одной неделе, не доверительный интервал по независимым нагрузкам. Seed 123 лучше на test, но остаётся seed 7, выбранный заранее по validation.",'','## Как рассказать в докладе','','1. Равномерное распределение ключей не гарантирует равномерную нагрузку: 20 популярных ключей дают около 29% запросов.','2. JCH уменьшает число перемещаемых ключей при расширении; размер объектов и TTL определяют реальные модельные байты переноса.','3. Маленький кластер дешевле, но чаще перегружается; большой платит за простаивающие ресурсы.','4. Пороговое управление реагирует на предыдущую нагрузку. Нейросетевой агент использует ещё тренд, время суток и цену изменения схемы.','5. Сравниваем разложение стоимости, перегрузку и перенос отдельно, чтобы не скрыть компромисс одной цифрой.','','## Ограничения','','Это результат условной модели на одной выборке и одной неделе. Мощность калибрована по train; цены серверов, перегрузки и миграции заданы как сценарные коэффициенты. Нет реального ClickHouse, измерений latency, репликации, сетевых задержек и очереди. Живая база восстановлена по set и TTL с пустого состояния, без информации об успешности и вытеснении. Метод sample100 не подтверждён, показатели не экстраполируются на Twitter. Горячий ключ не делится простым увеличением числа шардов. Для сильного исследовательского вывода нужны новые недели/кластеры и реальные измерения.','','Источники: [Twitter cache-trace](https://github.com/twitter/cache-trace), [CMU](https://ftp.pdl.cmu.edu/pub/datasets/twemcacheWorkload/open_source/sample100/), [OSDI 2020](https://www.usenix.org/conference/osdi20/presentation/yang). Данные CC BY 4.0; авторы Juncheng Yang, Yao Yue, Rashmi Vinayak.']
Path('RESULTS.md').write_text('> Исторический первый эксперимент. Ограничения и последующий аудит: [METHODOLOGY_REVIEW.md](METHODOLOGY_REVIEW.md).\n\n'+'\n'.join(lines)+'\n')
